def extend(i, dirs=None, stop_on_any=True, diag=False):
    H,W=len(i),len(i[0]); bgv,_=ccs(i); out=[row[:] for row in i]
    # process repeatedly until fixed point
    changed=True
    while changed:
        changed=False
