def comps(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=Counter(x for rr in g for x in rr).most_common(1)[0][0] and (r,c) not in seen:
                col=g[r][c]; q=deque([(r,c)]); seen.add((r,c)); comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<h and 0<=y<w and g[x][y]==col and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                out.append((col,len(comp),comp))
    return out
